/* ❌ TRADITIONAL CSS WAY */
// HTML:
<div class="chat-notification">
  <p class="chat-text">You have a new message!</p>
</div>

// CSS:
.chat-notification {
  padding: 1.5rem;
  max-width: 24rem;
  margin: 0 auto;
  background-color: white;
  border-radius: 0.75rem;
  box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1);
}
.chat-text { color: #1f2937; font-size: 1.25rem; }

/* ✅ TAILWIND WAY (No external CSS file needed!) */
<div class="p-6 max-w-sm mx-auto bg-white rounded-xl shadow-md">
  <p class="text-gray-800 text-xl">You have a new message!</p>
</div>
